try:
    vars['security_result_state'] = 'unperformed'
    if not isinstance(result, dict):
        result = dict(data=dict())
    result.pop('header', None)
    result.pop('headers', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = dict()
        result['data'] = d
    def yes(x):
        return x is True or isinstance(x, str) and x.lower() == 'true'
    field = str(vars.get('security_request_field', ''))
    hint = d.get('hint') == 'day_month_swapped'
    if hint:
        vars['security_result_state'] = 'hint'
        d['what_to_do_next'] = 'Do not advance or count a wrong answer. Ask the customer to say the birth month as a word, then retry that same question.'
    elif not yes(d.get('ok')):
        d['what_to_do_next'] = 'The answer was not checked successfully. Do not count a wrong answer or advance. Explain briefly and ask only for a complete readable answer to the same question; do not infer success.'
    elif yes(d.get('verified')):
        if field == 'date_of_birth':
            vars['dob_passed'] = 'yes'
            vars['security_state'] = 'phone_last4'
        elif field == 'phone_last4' and vars.get('dob_passed') == 'yes':
            vars['phone_passed'] = 'yes'
        if vars.get('dob_passed') == 'yes' and vars.get('phone_passed') == 'yes' and yes(d.get('all_verified')):
            vars['security_state'] = 'verified'
            vars['security_result_state'] = 'verified'
            d['what_to_do_next'] = 'Both security questions passed. Proceed immediately to the authorized silent account lookup; disclose nothing until it returns.'
        else:
            vars['security_result_state'] = 'field_passed'
            d['what_to_do_next'] = 'Ask only for the last four digits of the phone number on file. Preserve leading zeroes and wait for all four digits.' if field == 'date_of_birth' else 'Full verification was not confirmed. Explain that verification remains incomplete; do not look up or disclose the account.'
    else:
        count = int(vars.get('wrong_total', 0)) + 1
        left = d.get('wrong_answers_left')
        if isinstance(left, int) and not isinstance(left, bool) and 0 <= left <= 3:
            count = max(count, 3-left)
        vars['wrong_total'] = count
        vars['security_result_state'] = 'wrong'
        if count >= 3:
            vars['security_state'] = 'failed'
            d['what_to_do_next'] = 'Three wrong answers have ended verification. Direct the customer to the mobile app or a branch; disclose no debt. Complete the not_verified/failed closing.'
        else:
            vars['security_state'] = field
            d['what_to_do_next'] = 'That answer did not pass. Ask only the same failed question again; do not advance or disclose account information.'
    d['security_route'] = str(vars.get('security_state', 'date_of_birth'))
except Exception:
    vars['security_result_state'] = 'unperformed'
    if isinstance(result, dict):
        result.pop('header', None)
        result.pop('headers', None)
        result['data'] = dict(what_to_do_next='The check could not be interpreted. Explain that verification is incomplete and ask only the current question; do not look up the account.', security_route=str(vars.get('security_state', 'date_of_birth')))

