import json
try:
    vars['close_state'] = 'pending_response'
    body = config.get('body', dict())
    if isinstance(body, dict):
        outcome = str(vars.get('close_outcome', ''))
        reason = str(vars.get('close_reason', ''))
        if vars.get('transfer_state') == 'succeeded':
            outcome = 'transferred'
            reason = str(vars.get('transfer_reason', ''))
        elif outcome not in ['not_reached', 'not_verified']:
            records = vars.get('recorded_promises', [])
            if isinstance(records, str):
                records = json.loads(records)
            if isinstance(records, list) and records:
                outcome = 'promise'
                reason = ''
        if outcome:
            body['outcome'] = outcome
        if outcome in ['promise', 'paid']:
            body.pop('reason', None)
        elif reason:
            body['reason'] = reason
        vars['close_request'] = dict(outcome=body.get('outcome', ''), reason=body.get('reason', ''))
except Exception:
    vars['close_state'] = 'pending_response'
